select 'b3e91f6c47d2', m.mx + t.i, 'field', t.e
  from jsonb_array_elements($kb$[{"id": "dig-al", "url": "https://law.justia.com/codes/alabama/2022/title-37/chapter-15/section-37-15-4/", "text": "Alabama (AL) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Alabama 811 (al811.com). Wait before digging: Call at least 2 and not more than 10 working days before digging. Ticket life: A notice is good for 20 working days from the start date on the ticket. The app counts from the first legal dig day. Renew at least 2 working days before it expires if work goes on. Tolerance zone (hand dig or vacuum only): A new law (Jan 1, 2027) sets 18 inches plus the facility width. Check Alabama 811 for today's rule. White lining: Pre-mark in white when the location can't be described well enough. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Alabama 811 dig rules: wait before digging, ticket life, tolerance zone (Alabama 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Ala. Code 37-15-4 (2022); 2026 SB205 (changes from Jan 1, 2027); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-ak", "url": "https://cdn.pelicancorp.com/pdfs/26-ak811-excavator-handbook.pdf", "text": "Alaska (AK) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Alaska 811 (811ak.com). Wait before digging: Call at least 2 and not more than 15 working days before digging (10 to 20 in remote areas). Ticket life: The law sets no ticket expiry. Ask for a remark if marks fade. The app fills no expiry date for Alaska; enter the date printed on your ticket if it has one. Tolerance zone (hand dig or vacuum only): Marks within 24 inches of the facility (30 inches if deeper than 10 ft). White lining: Mark the dig area in white when it can't be clearly described (black on snow). Emergency: notify every operator right away and ask for a prompt locate. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Alaska 811 dig rules: wait before digging, tolerance zone (Alaska 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Alaska 811 excavator handbook 2026 (AS 42.30.400-490); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-az", "url": "https://www.azleg.gov/ars/40/00360-22.htm", "text": "Arizona (AZ) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Arizona 811 (arizona811.com). Wait before digging: Call at least 2 working days before digging. Working days skip weekends, legal holidays and the Friday after Thanksgiving. Ticket life: Marks are good for 15 working days from the day they were marked. The app counts from the call-in day, so its date can be a little early. Tell the operators at least 2 working days before the 15 working days run out if work goes on. Tolerance zone (hand dig or vacuum only): Dig by hand within 24 inches of a facility. White lining: Mark the dig area with white lining before you call (not needed on your own single-family home). Emergencies with immediate danger to life, health or property are treated differently. Take reasonable care to protect lines. Trench protection: ADOSH uses the federal rule: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Arizona 811 dig rules: wait before digging, ticket life, tolerance zone (Arizona 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "A.R.S. 40-360.22 (marking valid 15 working days, white lining); 2026 Laws ch. 147 (SB 1137): definitions, 24 in hand digging, emergencies; A.A.C. R20-5-601 (ADOSH adopts 29 CFR 1926); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-ar", "url": "https://read.nxtbook.com/gulf_energy_information/underground_infrastructure/march_2026/one_call_directory.html", "text": "Arkansas (AR) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Arkansas 811 (arkansas811.com). Wait before digging: not confirmed from the law, so ask Arkansas 811 and go by the dig date on your ticket. Ticket life: no fixed number of days is confirmed for Arkansas; go by the expiry on your ticket (the app fills no expiry date and asks for the date on the ticket). Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Arkansas 811 and treat at least 24 inches each side of the marks as hand-dig until you know. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Arkansas 811 dig rules: 811 center and what to check (Arkansas 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Center directory (name and site only); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-ca", "url": "https://california.public.law/codes/ca_gov't_code_section_4216.2", "text": "California (CA) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: USA North 811 (Northern California) and DigAlert (Southern California) (usanorth811.org, digalert.org). Wait before digging: Call at least 2 working days before digging, not counting the call day. Working days are Mon-Fri, 7 AM to 5 PM, not holidays. Call no more than 14 calendar days before work starts. Ticket life: A ticket is good for 28 days from the day it is issued. Renew online or by phone by the end of day 28 if work goes on. Tolerance zone (hand dig or vacuum only): 24 inches each side of the field mark. White lining: Mark the dig area (white) before you call. In an emergency you may dig without the 2-day wait. Call 811 as soon as you can. Trench protection: Cal/OSHA: protective system from 5 ft unless the competent person finds no cave-in hazard under 5 ft, or it is all stable rock (8 CCR 1541.1). Cal/OSHA permit needed for trenches or excavations 5 ft or deeper that anyone enters (8 CCR 341). Emergency repair of underground facilities is exempt. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "California 811 dig rules: wait before digging, ticket life, tolerance zone (USA North 811 / DigAlert)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Gov. Code 4216.2 (notice, 28-day ticket, delineate); Gov. Code 4216 (tolerance zone, working day, emergency); 8 CCR 1541.1 (protective systems from 5 ft); 8 CCR 341 (permit, 5 ft trenches); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-co", "url": "https://codes.findlaw.com/co/title-9-safety-industrial-and-commercial/co-rev-st-sect-9-1-5-103/", "text": "Colorado (CO) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Colorado 811 (colorado811.org). Wait before digging: Call at least 2 business days before digging, not counting the call day. Ticket life: Marks are good while clearly visible, but not more than 30 calendar days after the locate due date. Before the 30 days end, call again with at least 2 business days' notice. Tolerance zone (hand dig or vacuum only): 18 inches each side of the facility. Use nondestructive digging inside it. White lining: Mark the area in white (or by electronic white lining or an on-site meeting) when it can't be described on the ticket. Emergency: no advance notice needed. Take reasonable care, notify the owners and Colorado 811 as soon as you can. Trench protection: Federal OSHA: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Colorado 811 dig rules: wait before digging, ticket life, tolerance zone (Colorado 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "C.R.S. 9-1.5-103; app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-ct", "url": "https://portal.ct.gov/PURA/Gas-Pipeline-Safety/Call-Before-You-Dig/CBYD-Current-Provisions", "text": "Connecticut (CT) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Call Before You Dig (CBYD) (cbyd.com). Wait before digging: Call at least 2 full days (not weekends or holidays) and not more than 30 days before digging. Ticket life: A ticket expires 30 days from the day it is given. Past 30 days, call in again. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Call Before You Dig (CBYD) and treat at least 24 inches each side of the marks as hand-dig until you know. Emergency work: call the center right away, by phone as soon as you can. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Connecticut 811 dig rules: wait before digging, ticket life (Call Before You Dig (CBYD))", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "PURA: CBYD current provisions (RCSA 16-345-4); RCSA 16-345-4(d) (30-day expiry); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-de", "url": "https://delcode.delaware.gov/title26/c008/sc01/index.html", "text": "Delaware (DE) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Miss Utility of Delmarva (missutilitydelmarva.com). Wait before digging: Call at least 3 and not more than 12 business days before digging. Ticket life: A ticket is good for 12 business days after it is sent. On day 13 it expires. Get an update, remark or new ticket after it expires. Tolerance zone (hand dig or vacuum only): 24 inches from the outside of the facility. White lining: White lining is highly recommended when the exact spot can't be described. Emergency: the wait does not apply. Notify the center at the earliest moment. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Delaware 811 dig rules: wait before digging, ticket life, tolerance zone (Miss Utility of Delmarva)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Del. Code Title 26, ch. 8, subch. I (802, 806); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-dc", "url": "https://code.dccouncil.gov/us/dc/council/code/titles/34/chapters/27/index.full.html", "text": "District of Columbia (DC) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Miss Utility (missutility.net). Wait before digging: Notify at least 96 hours (not weekends or legal holidays) and not more than 10 days before digging. Ticket life: A notice is good for 15 days, not counting weekends and legal holidays. Ask for a remark 3 days before the end, or when marks fade. Tolerance zone (hand dig or vacuum only): Marks within 2 ft of the facility. Within 18 inches, expose it by hand. Imminent danger: the notice rule does not apply, but notify operators right away. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "District of Columbia 811 dig rules: wait before digging, ticket life, tolerance zone (Miss Utility)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "D.C. Code ch. 27 (34-2704, 34-2709); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-fl", "url": "https://m.flsenate.gov/statutes/556.105", "text": "Florida (FL) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Sunshine 811 (sunshine811.com). Wait before digging: Call at least 2 full business days before digging (10 for underwater work). Ticket life: Ticket information is good for 30 calendar days after you give it. Past 30 days, call in again. Tolerance zone (hand dig or vacuum only): Lines are marked within 24 inches of either side. Hand dig, pothole or vacuum inside the tolerance zone. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Florida 811 dig rules: wait before digging, ticket life, tolerance zone (Sunshine 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Fla. Stat. 556.105 (2026); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-ga", "url": "https://georgia811.com/?p=3343", "text": "Georgia (GA) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Georgia 811 (georgia811.com). Wait before digging: not confirmed from the law, so ask Georgia 811 and go by the dig date on your ticket. Ticket life: A locate request expires after 30 calendar days. Renew 3 business days before it expires. Tolerance zone (hand dig or vacuum only): 18 inches either side of the facility edge. White lining: White-line the site when it can't be described clearly enough. Georgia's wait is set as a \"notice period\" we could not confirm. Check Georgia 811. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Georgia 811 dig rules: ticket life, tolerance zone (Georgia 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Georgia 811 FAQ; O.C.G.A. 25-9-6 (2022); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-hi", "url": "https://data.capitol.hawaii.gov/hrscurrent/Vol05_Ch0261-0319/HRS0269E/HRS_0269E-0007.htm", "text": "Hawaii (HI) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Hawaii One Call Center (callbeforeyoudig.org/hawaii). Wait before digging: Call at least 5 working days and not more than 28 calendar days before digging. Ticket life: A ticket number is good for not more than 28 calendar days from issue. Revalidate before it expires. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Hawaii One Call Center and treat at least 24 inches each side of the marks as hand-dig until you know. The notice rule does not apply in an emergency. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Hawaii 811 dig rules: wait before digging, ticket life (Hawaii One Call Center)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "HRS 269E-7; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-id", "url": "https://dopl.idaho.gov/wp-content/uploads/2026/04/DAM-ID-Guide-to-Safe-Digging-26_27.pdf", "text": "Idaho (ID) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Digline (Most of Idaho) and Dig Safe North Idaho 811 (Bonner, Boundary, Kootenai) and North Idaho 811 (Benewah, Shoshone) (digline.com, digsafenorthidaho811.com, nid811.com). Wait before digging: Call at least 2 business days and not more than 10 business days before digging. Ticket life: Marks are good for no more than 4 weeks after the notice. Not started within 3 weeks of the notice: call again. Use an update request to extend. Tolerance zone (hand dig or vacuum only): 24 inches from the outside edges of the facility. Hand dig inside it. White lining: Pre-mark the dig path in white, unless the address or lot on the ticket shows it or you met on site. Imminent danger: no wait. Other emergencies: give emergency notice. The owner calls within 1 hour and comes within 2 hours. Trench protection: Federal OSHA: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Idaho 811 dig rules: wait before digging, ticket life, tolerance zone (Digline / Dig Safe North Idaho 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Idaho DOPL Guide to Safe Digging 2026-27 (Idaho Code 55-2205, 55-2207); Idaho DOPL one-call centers; app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-il", "url": "https://witnessslips.ilga.gov/legislation/ilcs/documents/022000500K4.htm", "text": "Illinois (IL) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: JULIE (Illinois outside Chicago) and Chicago 811 (DIGGER) (City of Chicago) (illinois1call.com, ipi.cityofchicago.org/Digger). Wait before digging: Give notice not less than 2 days and not more than 10 days before digging (law from Jan 1, 2025). Ticket life: The original notice expires after 25 days. Past 25 days, get an extension; pre-mark again if you want new marks. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask JULIE and treat at least 24 inches each side of the marks as hand-dig until you know. White lining: Pre-mark the dig area. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Illinois 811 dig rules: wait before digging, ticket life (JULIE / Chicago 811 (DIGGER))", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "220 ILCS 50/4 (P.A. 103-614, from Jan 1, 2025); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-in", "url": "https://codes.findlaw.com/in/title-8-utilities-and-transportation/in-code-sect-8-1-26-16/", "text": "Indiana (IN) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Indiana 811 (indiana811.org). Wait before digging: Call at least 2 full working days and not more than 10 calendar days before digging. Dig from 7 AM the next working day. Ticket life: A notice expires at 11:59 PM, 20 days after it is received. Past that, send a new locate request. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Indiana 811 and treat at least 24 inches each side of the marks as hand-dig until you know. White lining: White-line the site when you can't give an address, legal description or cross streets. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Indiana 811 dig rules: wait before digging, ticket life (Indiana 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Ind. Code 8-1-26-16 (2026); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-ia", "url": "https://www.legis.iowa.gov/docs/code/2025/480.4.pdf", "text": "Iowa (IA) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Iowa One Call (iowaonecall.com). Wait before digging: Give notice so digging starts after a 48-hour period. Ticket life: A notice is good for 25 calendar days starting the day the 48 hours end. Ask for a remark if needed. Tolerance zone (hand dig or vacuum only): The facility location includes 18 inches either side. White lining: Mark the proposed area with white paint, flags or stakes unless an exception applies. Emergency: you may start right away. Notify Iowa One Call as soon as practical. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Iowa 811 dig rules: wait before digging, ticket life, tolerance zone (Iowa One Call)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Iowa Code 480.4 (2025); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-ks", "url": "https://ksrevisor.gov/statutes/chapters/ch66/066_018_0004.html", "text": "Kansas (KS) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Kansas 811 (kansas811.com). Wait before digging: Call at least 2 full working days and not more than 20 calendar days before the start date. Ticket life: A notice is good for 20 calendar days after the start date. The app counts from the first legal dig day. Update the notice to go on. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Kansas 811 and treat at least 24 inches each side of the marks as hand-dig until you know. White lining: White-line the site when the operator asks. The notice rule does not apply in an emergency. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Kansas 811 dig rules: wait before digging, ticket life (Kansas 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "K.S.A. 66-1804; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-ky", "url": "https://law.justia.com/codes/kentucky/chapter-367/section-367-4911/", "text": "Kentucky (KY) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Kentucky 811 (kentucky811.org). Wait before digging: Call at least 2 and not more than 10 full working days before digging. Ticket life: A locate request is good for 21 calendar days from the day it was made. Ask for a remark 2 working days before each 21 days end. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Kentucky 811 and treat at least 24 inches each side of the marks as hand-dig until you know. Gas or hazardous liquid leak: stop and call 911. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Kentucky 811 dig rules: wait before digging, ticket life (Kentucky 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "KRS 367.4911 (2025); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-la", "url": "https://read.nxtbook.com/gulf_energy_information/underground_infrastructure/march_2026/one_call_directory.html", "text": "Louisiana (LA) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Louisiana 811 (louisiana811.com). Wait before digging: not confirmed from the law, so ask Louisiana 811 and go by the dig date on your ticket. Ticket life: no fixed number of days is confirmed for Louisiana; go by the expiry on your ticket (the app fills no expiry date and asks for the date on the ticket). Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Louisiana 811 and treat at least 24 inches each side of the marks as hand-dig until you know. Louisiana changed its law in 2023 and we could not confirm the current wait and ticket life. Check Louisiana 811. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Louisiana 811 dig rules: 811 center and what to check (Louisiana 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Center directory (name and site only); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-me", "url": "https://legislature.maine.gov/statutes/23/title23sec3360-A.html", "text": "Maine (ME) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Dig Safe (digsafe.com). Wait before digging: Call at least 3 business days and not more than 30 calendar days before digging. Ticket life: Start within 30 days. If the work is not done 60 days after notice, call again. Call again after 60 days or if the work area grows. Tolerance zone (hand dig or vacuum only): No mechanical digging within 18 inches of a mark until the line is exposed. White lining: Mark the proposed dig area before you call. Emergency: notify the center and mark the site first if you can. Start within 12 hours of the notice. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Maine 811 dig rules: wait before digging, ticket life, tolerance zone (Dig Safe)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "23 M.R.S. 3360-A; Dig Safe excavator manual (Oct 2024); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-md", "url": "https://mgaleg.maryland.gov/2022rs/Chapters_noln/CH_435_hb0994t.pdf", "text": "Maryland (MD) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Miss Utility (missutility.net). Wait before digging: Pick a start date at least 3 and not more than 12 business days after the ticket. Ticket life: A ticket is good for 12 business days after the start date you picked. The app counts from the first legal dig day. Tolerance zone (hand dig or vacuum only): Marks within 18 inches either side. No power equipment within 18 inches of the marks. White lining: Miss Utility suggests marking the dig site in white. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Maryland 811 dig rules: wait before digging, ticket life, tolerance zone (Miss Utility)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "2022 Md. Laws ch. 435 (HB 994); Miss Utility: information for excavators; app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-ma", "url": "https://digsafe.com/data/file_uploads/DGS Excavator Manual OCTOBER 2024 WEB.pdf", "text": "Massachusetts (MA) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Dig Safe (digsafe.com). Wait before digging: Call at least 72 hours before digging, not counting weekends and holidays. Ticket life: Tickets expire 30 days from the day they are issued. Renew only if work will happen within 30 days. Tolerance zone (hand dig or vacuum only): The facility width plus 18 inches each side. White lining: Premark the dig area in white before you call (some long digs are exempt). Emergency notice the same day. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Massachusetts 811 dig rules: wait before digging, ticket life, tolerance zone (Dig Safe)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Dig Safe excavator manual (Oct 2024); Dig Safe FAQ; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-mi", "url": "https://ombudsman.legislature.mi.gov/documents/mcl/pdf/MCL-460-725.pdf", "text": "Michigan (MI) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: MISS DIG 811 (missdig811.org). Wait before digging: Give notice at least 72 hours (not counting non-business days) and not more than 14 calendar days before digging. Ticket life: A ticket is good for 21 days from the start date (180 days if the notice says the work will take longer). The app counts from the first legal dig day. Tolerance zone (hand dig or vacuum only): Caution zone: 48 inches either side of the marks. Expose marked lines by soft digging. White lining: White-line before the ticket when the parcel can't be described. Give prompt emergency notice. Do only the work the emergency needs. Trench protection: MIOSHA Part 9 (Michigan's own rule): slope or support the sides of an excavation more than 5 ft deep, and protect a shallower one when the ground may move (R 408.40941). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Michigan 811 dig rules: wait before digging, ticket life, tolerance zone (MISS DIG 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "MCL 460.725; MCL 460.723 (caution zone, business day); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-mn", "url": "https://www.revisor.mn.gov/statutes/?id=216D.04", "text": "Minnesota (MN) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Gopher State One Call (gopherstateonecall.org). Wait before digging: Give notice at least 48 hours (not the notice day, weekends or holidays) and not more than 14 calendar days before digging. Ticket life: A notice is good for 14 calendar days from the start time on it. The app counts from the first legal dig day. Past 14 days, give a new notice (or arrange mark checks: then 6 months). Tolerance zone (hand dig or vacuum only): Marks within 2 ft. Find the exact spot before digging within 2 ft of the mark. The notice rule does not apply in an emergency. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Minnesota 811 dig rules: wait before digging, ticket life, tolerance zone (Gopher State One Call)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Minn. Stat. 216D.04 (2025); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-ms", "url": "https://ms811.org/wp-content/uploads/2025/04/2025-Excavation-Law-Amendments-Summary.pdf", "text": "Mississippi (MS) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Mississippi 811 (ms811.org). Wait before digging: not confirmed from the law, so ask Mississippi 811 and go by the dig date on your ticket. Ticket life: Normal and emergency tickets are good for 20 calendar days (from July 1, 2025). Tolerance zone (hand dig or vacuum only): 18 inches from each side of the marks, plus half the diameter if shown. White lining: Pre-mark the area unless it is electronically pre-marked. Operators respond to emergency tickets within 2 hours. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Mississippi 811 dig rules: ticket life, tolerance zone (Mississippi 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Mississippi 811: 2025 law changes; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-mo", "url": "https://revisor.mo.gov/main/OneSection.aspx?section=319.026", "text": "Missouri (MO) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Missouri 811 (missouri-811.org). Wait before digging: Call at least 2 and not more than 10 working days before digging. Ticket life: Not started within 10 working days: ask for a relocate first. The app fills no expiry date for Missouri; enter the date printed on your ticket if it has one. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Missouri 811 and treat at least 24 inches each side of the marks as hand-dig until you know. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Missouri 811 dig rules: wait before digging (Missouri 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "RSMo 319.026; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-mt", "url": "https://read.nxtbook.com/gulf_energy_information/underground_infrastructure/march_2026/one_call_directory.html", "text": "Montana (MT) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Montana 811 (montana811.org). Wait before digging: not confirmed from the law, so ask Montana 811 and go by the dig date on your ticket. Ticket life: no fixed number of days is confirmed for Montana; go by the expiry on your ticket (the app fills no expiry date and asks for the date on the ticket). Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Montana 811 and treat at least 24 inches each side of the marks as hand-dig until you know. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Montana 811 dig rules: 811 center and what to check (Montana 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Center directory (name and site only); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-ne", "url": "https://law.justia.com/codes/nebraska/chapter-76/statute-76-2321/", "text": "Nebraska (NE) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Nebraska 811 (ne1call.com). Wait before digging: Call at least 2 full business days and not more than 10 business days before digging. Ticket life: Start within 17 calendar days of the ticket start date or give a new notice. The app fills no expiry date for Nebraska; enter the date printed on your ticket if it has one. Tolerance zone (hand dig or vacuum only): 18 inches either side of the mark plus half the facility width. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Nebraska 811 dig rules: wait before digging, tolerance zone (Nebraska 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Neb. Rev. Stat. 76-2321; Nebraska One-Call Notification System Act (76-2323); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-nv", "url": "https://nevada.public.law/statutes/nrs_455.110", "text": "Nevada (NV) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: USA North 811 (usanorth811.org). Wait before digging: Call at least 2 working days (7 AM to 5 PM, not holidays) and not more than 28 calendar days before digging. Ticket life: A ticket is good for 28 calendar days from the day it is issued. Renew by the end of day 28 if work goes on and marks are still clear. Two renewals at most, then a new ticket. Tolerance zone (hand dig or vacuum only): The facility can be up to 24 inches either side. Hand tools only within 24 inches. White lining: Mark the proposed dig area (white paint, flags, stakes or whiskers). In an emergency you may dig without the wait. Tell the operator as soon as you can. Trench protection: Nevada OSHA enforces the federal rule: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Nevada 811 dig rules: wait before digging, ticket life, tolerance zone (USA North 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "NRS 455.110 (notice, premark, emergency); NRS 455 (24 in approximate location, working day); USA North 811 Nevada 2025 handbook (28 days, 2 renewals); Nevada OSHA letter: enforces 29 CFR 1926 Subpart P; app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-nh", "url": "https://digsafe.com/data/file_uploads/DGS Excavator Manual OCTOBER 2024 WEB.pdf", "text": "New Hampshire (NH) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Dig Safe (digsafe.com). Wait before digging: Call at least 72 hours before digging, not counting weekends and holidays. Ticket life: Tickets expire 30 days from the day they are issued. Renew only if work will happen within 30 days. Tolerance zone (hand dig or vacuum only): The facility width plus 18 inches each side. White lining: Premark the dig area in white before you call (some long digs are exempt). Emergency notice the same day. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "New Hampshire 811 dig rules: wait before digging, ticket life, tolerance zone (Dig Safe)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Dig Safe excavator manual (Oct 2024); Dig Safe FAQ; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-nj", "url": "https://nj.gov/bpu/pdf/rules/Chapter%202 One Call Rules 10.28.21 Clean Version.pdf", "text": "New Jersey (NJ) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: New Jersey One Call (nj1-call.org). Wait before digging: Call at least 3 business days before digging. Work must start within 10 business days of the notice. Ticket life: A notice is good for 45 business days if work starts within 10 business days and the marks are kept. After 45 business days, give a new notice. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask New Jersey One Call and treat at least 24 inches each side of the marks as hand-dig until you know. White lining: White premarking is optional but encouraged. Emergency: notify the center as soon as you can without delaying the work. Gas or liquid line damage: call 911. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "New Jersey 811 dig rules: wait before digging, ticket life (New Jersey One Call)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "N.J.A.C. 14:2 (BPU one-call rules); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-nm", "url": "https://www.srca.nm.gov/parts/title18/18.060.0005.html", "text": "New Mexico (NM) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: New Mexico 811 (nm811.org). Wait before digging: Give notice 2 working days ahead, not counting the notice day. Operators have 2 full working days to mark. Ticket life: Marks are good for 15 working days from the end of the notice period. Wide-area tickets must be reaffirmed every 15 working days. Tolerance zone (hand dig or vacuum only): Within 18 inches either side of a mark, expose the line by hand or vacuum first. White lining: Pre-mark the actual dig site in white in towns. Outside towns, pre-mark or give GPS points. Emergency locates: marked as soon as practical, ideally within 2 hours. Trench protection: NM OSHA adopts the federal rule: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "New Mexico 811 dig rules: wait before digging, ticket life, tolerance zone (New Mexico 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "18.60.5 NMAC (Pipeline Safety Bureau excavation rule); 11.5.3 NMAC (NM OSHA adopts 29 CFR 1926); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-ny", "url": "https://dps.ny.gov/system/files/documents/2025/06/ss753-booklet-2025.05.09-update.pdf", "text": "New York (NY) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: UDig NY (New York outside NYC and Long Island) and New York 811 (New York City and Long Island) (udigny.org, newyork-811.com). Wait before digging: Call at least 2 and not more than 10 working days before the start date, not counting the call day. Ticket life: No set ticket life. A delay of more than 10 working days needs a new notice for the new start date. The app fills no expiry date for New York; enter the date printed on your ticket if it has one. Tolerance zone (hand dig or vacuum only): Two feet either side of the center line (plus half the diameter if known). White lining: Premark in white when needed to identify the site. Emergency work may start right away. Notify the one-call system as soon as possible. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "New York 811 dig rules: wait before digging, tolerance zone (UDig NY / New York 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "NY PSC 16 NYCRR Part 753 booklet (2025); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-nc", "url": "https://www.ncleg.gov/EnactedLegislation/Statutes/PDF/BySection/Chapter_87/GS_87-122.pdf", "text": "North Carolina (NC) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: NC811 (nc811.org). Wait before digging: Call at least 3 full working days before the start date. Ticket life: A notice expires 28 calendar days after the work start date. The app counts from the first legal dig day. Past that, give a new notice. Tolerance zone (hand dig or vacuum only): 24 inches applies only to oil, gas transmission and electric transmission lines (no mechanized digging). White lining: Premark in white when the area can't be identified from the notice. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "North Carolina 811 dig rules: wait before digging, ticket life, tolerance zone (NC811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "G.S. 87-122; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-nd", "url": "https://law.counselstack.com/statute/nd/49-23-04", "text": "North Dakota (ND) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: North Dakota One Call (ndonecall.com). Wait before digging: not confirmed from the law, so ask North Dakota One Call and go by the dig date on your ticket. Ticket life: A locate is good for 21 days after the planned dig date. The app counts from the first legal dig day. Not started in 21 days: ask for a relocate. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask North Dakota One Call and treat at least 24 inches each side of the marks as hand-dig until you know. White lining: Give site identification (white marks or other means) unless an exception applies. Emergency: no advance notice. Notify the center as soon as practical. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "North Dakota 811 dig rules: ticket life (North Dakota One Call)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "N.D.C.C. 49-23-04; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-oh", "url": "https://oups.org/wp-content/uploads/2026/06/OHIO811_Excavator-Manual_English_June-2026.pdf", "text": "Ohio (OH) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: OHIO811 (oups.org). Wait before digging: Call at least 2 working days (not counting the call day) and not more than 16 calendar days before digging. Ticket life: No ticket expiry is stated. Keep the ticket number for the whole job. The app fills no expiry date for Ohio; enter the date printed on your ticket if it has one. Tolerance zone (hand dig or vacuum only): The facility width plus 18 inches each side. White lining: Premark with white paint unless an exception applies. Emergency tickets are by phone only, for real emergencies. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Ohio 811 dig rules: wait before digging, tolerance zone (OHIO811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "OHIO811 excavator manual, June 2026 (ORC 3781.25-.29); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-ok", "url": "https://law.counselstack.com/statute/ok/63/63-142.6", "text": "Oklahoma (OK) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: OKIE811 (okie811.org). Wait before digging: Give notice at least 48 hours (not the notice day, weekends or holidays) before digging. Ticket life: A notice expires 14 calendar days from the start date. The app counts from the first legal dig day. Give a new notice to keep digging. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask OKIE811 and treat at least 24 inches each side of the marks as hand-dig until you know. Emergency: you may start right away with reasonable care. Notify operators promptly. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Oklahoma 811 dig rules: wait before digging, ticket life (OKIE811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "63 O.S. 142.6; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-or", "url": "https://digsafelyoregon.com/resources/faq/", "text": "Oregon (OR) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Oregon 811 (Oregon Utility Notification Center) (digsafelyoregon.com). Wait before digging: Call at least 2 full business days and not more than 10 business days before digging. After 5 PM counts as the next business day. Ticket life: A ticket is good for 45 calendar days from the day it was sent in. Past 45 days, call in a new locate request. Tolerance zone (hand dig or vacuum only): 24 inches each side of the facility. Hand tools or non-invasive methods inside it. White lining: Mark the proposed dig area in white before you call. Emergency locates are for immediate danger to life or property, or to essential service. There is no legal \"priority\" locate. Trench protection: Oregon OSHA adopts the federal rule: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Oregon 811 dig rules: wait before digging, ticket life, tolerance zone (Oregon 811 (Oregon Utility Notification Center))", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Oregon 811 FAQ (OAR 952-001-0040, -0050, -0060, -0090); OAR 952-001-0070 (24 in marking, white premark); OAR 437-003-0001 (Oregon OSHA adopts 1926.650-652); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-pa", "url": "https://codes.findlaw.com/pa/title-73-ps-trade-and-commerce/pa-st-sect-73-177/", "text": "Pennsylvania (PA) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Pennsylvania 811 (pa1call.org). Wait before digging: not confirmed from the law, so ask Pennsylvania 811 and go by the dig date on your ticket. Ticket life: no fixed number of days is confirmed for Pennsylvania; go by the expiry on your ticket (the app fills no expiry date and asks for the date on the ticket). Tolerance zone (hand dig or vacuum only): Lines are marked within 18 inches of the outside wall. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Pennsylvania 811 dig rules: tolerance zone (Pennsylvania 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "73 P.S. 177; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-ri", "url": "https://digsafe.com/data/file_uploads/DGS Excavator Manual OCTOBER 2024 WEB.pdf", "text": "Rhode Island (RI) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Dig Safe (digsafe.com). Wait before digging: Call at least 72 hours before digging, not counting weekends and holidays. Ticket life: Tickets do not expire as long as the marks are kept. The app fills no expiry date for Rhode Island; enter the date printed on your ticket if it has one. Tolerance zone (hand dig or vacuum only): The facility width plus 18 inches each side. White lining: Premark the dig area in white before you call (digs over 500 ft are exempt). Emergency notice the same day. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Rhode Island 811 dig rules: wait before digging, tolerance zone (Dig Safe)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Dig Safe excavator manual (Oct 2024); Dig Safe FAQ; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-sc", "url": "https://sc811.com/wp-content/uploads/2026/05/Excavator-Manual-2026.pdf", "text": "South Carolina (SC) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: SC811 (sc811.com). Wait before digging: Operators have 3 full working days to mark, not counting the call day. Ticket life: A normal ticket is good for 15 working days from its start time. Send an extension before it expires (a remark gets a new ticket). Tolerance zone (hand dig or vacuum only): 24 inches each side of the mark, plus half the diameter if known. White lining: Pre-mark in white when the site can't be clearly identified. Emergency: exempt from the notice rule, but notify SC811 and the operators as soon as practicable. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "South Carolina 811 dig rules: wait before digging, ticket life, tolerance zone (SC811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "SC811 excavator manual 2026 (S.C. Code 58-36-60, -70); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-sd", "url": "https://mylrc.sdlegislature.gov/api/Documents/300764.pdf", "text": "South Dakota (SD) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: South Dakota 811 (sdonecall.com). Wait before digging: Give notice at least 48 hours ahead. The 48 hours start 12:01 AM the next day and skip weekends and state holidays (2026 law). Ticket life: no fixed number of days is confirmed for South Dakota; go by the expiry on your ticket (the app fills no expiry date and asks for the date on the ticket). Tolerance zone (hand dig or vacuum only): Marks within 18 inches of the facility; keep 18 inches between marks and machine teeth. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "South Dakota 811 dig rules: wait before digging, tolerance zone (South Dakota 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "2026 SB 9 (SDCL 49-7A-5, -8); app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-tn", "url": "https://codes.findlaw.com/tn/title-65-public-utilities-and-carriers/tn-code-sect-65-31-106/", "text": "Tennessee (TN) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Tennessee 811 (tenn811.com). Wait before digging: Call at least 3 and not more than 10 full working days before digging. Ticket life: A notice is good for 15 calendar days from the start date. The app counts from the first legal dig day. Give a new notice at least 3 working days before day 15 if work goes on. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask Tennessee 811 and treat at least 24 inches each side of the marks as hand-dig until you know. White lining: Mark the area with white stakes, white paint or electronic white lining unless an exception applies. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Tennessee 811 dig rules: wait before digging, ticket life (Tennessee 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Tenn. Code 65-31-106; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-tx", "url": "https://texas.public.law/statutes/tex._util._code_section_251.151", "text": "Texas (TX) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Texas811 (texas811.org). Wait before digging: Call at least 48 hours before digging, not counting weekends and legal holidays, and not more than 14 days ahead. A Saturday call: dig from Tuesday 11:59 AM. Ticket life: A routine ticket is good for 14 working days from the call (Railroad Commission rule). If the work isn't done, refresh the ticket for the area still to dig. Tolerance zone (hand dig or vacuum only): Pipelines: half the pipe diameter plus 18 inches each side (16 TAC 18.2). The one-call law sets no zone for other lines; Texas811 uses 18 inches. White lining: White-line the area before you call when the site can't be clearly described on the ticket. Emergency: danger to life, health or property, or urgent service restoration. Call 811 for an emergency ticket. Gas line hit: call 911. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Texas 811 dig rules: wait before digging, ticket life, tolerance zone (Texas811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Utilities Code 251.151 (48 hours, 14 days); 16 TAC Chapter 18 (14-day ticket, working days, tolerance zone, white lining); RRC excavator brochure: tickets expire in 14 working days; Texas811 FAQ; app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-ut", "url": "https://le.utah.gov/xcode/Title54/Chapter8A/C54-8a-S4_2024050120240501.html", "text": "Utah (UT) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Blue Stakes of Utah 811 (bluestakes.org). Wait before digging: Give notice at least 48 hours (business days) and not more than 14 days before digging. The clock starts 8 AM the next business day. Ticket life: A ticket is good for 21 days from the day notice was given. New tickets expire at 8 AM on day 21. Renew at least 48 hours and no sooner than 7 days before day 21. A renewal adds 21 days from the old expiry. Tolerance zone (hand dig or vacuum only): 24 inches either side of the facility mark (or half the marked diameter plus 24 inches from center). White lining: If the site can't be described, outline it using the uniform color code. The notice rule does not apply in an emergency. Trench protection: UOSH adopts the federal rule: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Utah 811 dig rules: wait before digging, ticket life, tolerance zone (Blue Stakes of Utah 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Utah Code 54-8a-4 (48 hours, 14 days, 21-day notice, renewal); Utah Code 54-8a-2 (tolerance zone 24 in, emergency); Blue Stakes: state law (21 days, 8 AM); Utah Admin. Code R614-1-4 (UOSH adopts 29 CFR 1926); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-vt", "url": "https://digsafe.com/data/file_uploads/DGS Excavator Manual OCTOBER 2024 WEB.pdf", "text": "Vermont (VT) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Dig Safe (digsafe.com). Wait before digging: Call at least 72 hours before digging, not counting weekends and holidays. Ticket life: Tickets expire 30 days from the day they are issued. Renew only if work will happen within 30 days. Tolerance zone (hand dig or vacuum only): The facility width plus 18 inches each side. White lining: Premark the dig area in white before you call (digs over 500 ft are exempt). Emergency notice the same day. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Vermont 811 dig rules: wait before digging, ticket life, tolerance zone (Dig Safe)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Dig Safe excavator manual (Oct 2024); Dig Safe FAQ; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-va", "url": "https://law.lis.virginia.gov/vacode/56-265.17/", "text": "Virginia (VA) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: VA811 (va811.com). Wait before digging: not confirmed from the law, so ask VA811 and go by the dig date on your ticket. Ticket life: A notice is good for 15 working days from 7 AM the next working day (or the scheduled date if later). Ask for a remark 3 working days before the end, or when marks fade. A remark adds 15 working days. Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask VA811 and treat at least 24 inches each side of the marks as hand-dig until you know. White lining: Mark the route or site with white paint when a location can't be given. Virginia: dig only after every operator has marked or posted a positive response. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Virginia 811 dig rules: ticket life (VA811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Va. Code 56-265.17; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-wa", "url": "https://app.leg.wa.gov/RCW/default.aspx?cite=19.122.030", "text": "Washington (WA) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Washington 811 (washington811.com). Wait before digging: Call at least 2 full business days and not more than 10 full business days before digging. From Jan 1, 2026, wait for a positive response from every operator. Ticket life: Marks are good for 45 calendar days from the day you gave notice. Past 45 days, give a new notice. Tolerance zone (hand dig or vacuum only): Marks are accurate to within 24 inches of each side of the facility. White lining: Mark the dig area with white lining or white pin flags before you call. Emergency: clear and present danger to life, health or property, or an unplanned outage with a crew on site or on the way. Trench protection: Washington DOSH: protective system from 4 ft unless the competent person finds no cave-in hazard, or it is all stable rock (WAC 296-155-657). From June 1, 2026: a written trench work plan when a protective system is needed, and a competent person on site during trench work. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Washington 811 dig rules: wait before digging, ticket life, tolerance zone (Washington 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "RCW 19.122.030 (white lining, notice, 45 days); RCW 19.122.020 (24 in reasonable accuracy, business day, emergency); UTC: dig law changes from July 27, 2025; WAC 296-155-657 (protective system from 4 ft); app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-wv", "url": "https://code.wvlegislature.gov/24C-1-5/", "text": "West Virginia (WV) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: WV811 (wv811.com). Wait before digging: Give notice at least 48 hours (not weekends or holidays) and not more than 10 work days before digging. Ticket life: no fixed number of days is confirmed for West Virginia; go by the expiry on your ticket (the app fills no expiry date and asks for the date on the ticket). Tolerance zone (hand dig or vacuum only): not confirmed from the law; ask WV811 and treat at least 24 inches each side of the marks as hand-dig until you know. A break or leak that causes an emergency: call 911 right away. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "West Virginia 811 dig rules: wait before digging (WV811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "W. Va. Code 24C-1-5; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-wi", "url": "https://docs.legis.wisconsin.gov/statutes/statutes/182/0175/2?up=1", "text": "Wisconsin (WI) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Diggers Hotline (diggershotline.com). Wait before digging: Give notice at least 3 working days before digging. Ticket life: No set ticket life. Give a new notice if marks are lost, or work doesn't start within 10 days of the scheduled start, or stops more than 10 days. The app fills no expiry date for Wisconsin; enter the date printed on your ticket if it has one. Tolerance zone (hand dig or vacuum only): Keep 18 inches between a mark and the machine's cutting edge. In an emergency, take all reasonable care and notify owners as soon as you can. Trench protection: Federal OSHA covers private crews here: protective system from 5 ft (29 CFR 1926.652). Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Wisconsin 811 dig rules: wait before digging, tolerance zone (Diggers Hotline)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Wis. Stat. 182.0175; app state table checked 2026-11-19", "confidence": "medium"}, {"id": "dig-wy", "url": "https://law.counselstack.com/statute/wy/37-12-302", "text": "Wyoming (WY) 811 rules as the app uses them, checked 2026-11-19. Call 811 or go online: Wyoming 811 (onecallofwyoming.com). Wait before digging: Call at least 2 full business days and not more than 14 business days before digging. Ticket life: For longer jobs, renew the notice at least once every 14 business days. Renew every 14 business days. Tolerance zone (hand dig or vacuum only): Marks within 24 inches of the facility. Emergency digging is exempt from the time limits. Trench protection: State OSHA plan. Federal OSHA's 5 ft rule is the floor; we have not checked whether this plan is stricter. Rules change. If your ticket or the 811 center says something different, go by them. A line hit that leaks gas or sparks: get everyone away and call 911, then the owner.", "title": "Wyoming 811 dig rules: wait before digging, ticket life, tolerance zone (Wyoming 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "W.S. 37-12-302; app state table checked 2026-11-19", "confidence": "high"}, {"id": "dig-basics-1", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.651", "text": "Every state has a one-call law and 811 reaches the right center from anywhere in the country. The steps are the same everywhere: mark your dig area in white, call or go online before you dig, wait the legal notice time, check that every utility has marked or answered, dig by hand or vacuum inside the tolerance zone, keep the marks visible, and renew the ticket before it runs out. What changes by state is the numbers. Of the 51 state tables in the app (50 states and DC, checked 2026-11-19): the wait is 2 working days in 28 states and 3 in 13, and longer in a few; ticket life runs from about two weeks to 60 days, counted in working days in some states and calendar days in others, and from the call in some and from the legal dig date in others; the tolerance zone is 18 inches each side in about as many states as 24 inches, measured from the mark in some and from the outside edge of the line in others. So never carry one state's numbers to the next job: ask for your job's state by name (for example 'how long is a ticket good for in Texas'), or open Locates and tap Rules for the state. Federal OSHA adds its own duty in every state: find out where underground lines are before opening an excavation, and protect, support or remove them while it is open (29 CFR 1926.651(b)). The ticket, the 811 center and the state law govern; this is a plain-language summary.", "title": "811 before you dig: what is the same everywhere and what changes by state", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "State one-call laws as listed in the app's state rules table (51 rows, checked 2026-11-19); 29 CFR 1926.651(b)", "confidence": "high"}, {"id": "plan-mi-trench-1", "url": "https://www.law.cornell.edu/regulations/michigan/Mich-Admin-Code-R-408-40941", "text": "Michigan runs its own OSHA plan (MIOSHA) and has its own excavation rule, Construction Safety Standard Part 9, Excavation, Trenching and Shoring (R 408.40901 to R 408.40953, last amended effective January 3, 2024). Main numbers: the side of an excavation more than 5 ft deep must be sloped as Table 1 of Part 9 prescribes unless it is supported as the part prescribes; an excavation less than 5 ft deep must also be protected when examination of the ground shows hazardous earth movement may be expected (R 408.40941). Table 1 is Michigan's own table of maximum angles of repose by soil; read the table in Part 9 itself rather than assuming the federal Appendix B slopes. A competent person makes an ongoing inspection of the excavation or trench (R 408.40932). An excavation 48 inches or more deep with an employee in it needs a ladder extending at least 3 ft above the top (or other egress), with no more than 25 ft of lateral travel along the trench wall to reach it, and excavated material is kept at least 2 ft back from the edge (R 408.40933). A trench box or shield may be used in place of shoring or sloping (R 408.40945). Deep or unusual protective systems need a registered professional engineer's design (R 408.40942). Plain-language summary; the MIOSHA rule text and your competent person govern.", "title": "Michigan trench rules (MIOSHA Part 9): at what depth sloping, shoring or a trench box is required (over 5 ft), ladder at 4 ft", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "Mich. Admin. Code R 408.40932, R 408.40933, R 408.40941, R 408.40942, R 408.40945 (MIOSHA Construction Safety Standard Part 9, eff. 1/3/2024); checked 2026-11-20", "confidence": "high"}, {"id": "plan-or-confined-1", "url": "https://www.law.cornell.edu/regulations/oregon/Or-Admin-Code-SS-437-002-0146", "text": "Oregon runs its own OSHA plan and uses one confined space rule for all work, construction included: OAR 437-002-0146 \"applies to all activities in confined spaces\" (it has applied to construction work since March 1, 2015). Excavation work and underground construction under Oregon's construction rules are excluded, but sanitary sewer spaces stay covered. Numbers match federal: a hazardous atmosphere is oxygen below 19.5 percent or above 23.5 percent, flammable gas, vapor or mist above 10 percent of its lower flammable limit, or a toxic substance above its Oregon OSHA limit. Rescue: arrange it before entry and contact an off-site rescue service ahead of time; counting on calling 911 when something goes wrong does not meet the rule. Rescuers practice permit-space rescue at least every 12 months; use non-entry retrieval with a harness and line where feasible, with a mechanical device for vertical spaces more than 5 ft deep. Alternate entry (no permit) is allowed only when every hazard is eliminated, or all physical hazards are eliminated and the air hazards are controlled by continuous ventilation, with written procedures, testing with a calibrated meter, continuous monitoring and a record of each entry; a tag alone does not eliminate a hazard, and continuous systems such as sewers have extra conditions. The entry supervisor and your company program decide; this is a plain-language summary of the rule.", "title": "Oregon confined space rule (OAR 437-002-0146): one rule for construction and general industry, sewers included", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "Or. Admin. Code 437-002-0146 (Oregon OSHA Confined Spaces; OSHA 6-2012, 5-2014, 3-2015); checked 2026-11-20", "confidence": "high"}, {"id": "plan-wa-confined-1", "url": "https://www.law.cornell.edu/regulations/washington/WAC-296-809-100", "text": "Washington runs its own OSHA plan (DOSH, at Labor and Industries) and its confined space rule is chapter 296-809 of the state code. Its scope section says the chapter applies to all confined spaces: when you have confined spaces in your workplace, when your employees enter another employer's confined spaces, when a contractor enters yours, and when you provide confined space rescue. A table in the scope section tells which sections apply to permit-required spaces, alternative entry methods, spaces that are never entered, spaces only a contractor enters, and rescue services; where another Washington chapter also applies and they conflict, follow the more specific requirement. Cite chapter 296-809 on a Washington job rather than the federal Subpart AA section numbers; the federal text in the app's OSHA library is a guide to the same ideas (permit, air testing, attendant, rescue), not the Washington wording. The entry supervisor and your company program decide.", "title": "Washington confined space rule (chapter 296-809): covers all confined spaces, your own and other employers'", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "WAC 296-809-100 (scope; WSR 04-03-081, 15-24-102, 18-02-071); checked 2026-11-20", "confidence": "medium"}, {"id": "plan-trench-depth-1", "url": "https://www.osha.gov/stateplans", "text": "Federal OSHA requires a protective system (sloping, benching, shoring or a shield) in an excavation 5 ft or deeper unless it is entirely in stable rock, and in a shallower one when the competent person sees a cave-in hazard (29 CFR 1926.652). Twenty-one states run their own OSHA plan for private construction crews; a plan must be at least as protective as federal and may be stricter, so on those jobs cite the state rule. What has been checked against the state's own rule text so far (as of 2026-11-20): Washington requires protection at 4 ft and, since June 1, 2026, a written trench work plan and a competent person on site during trench work; California keeps 5 ft and adds a Cal/OSHA permit for excavations 5 ft or deeper that people enter; Michigan uses its own Part 9 (slope or support over 5 ft, with its own angle table); Arizona, Nevada, New Mexico, Oregon and Utah adopt the federal excavation standard, so 5 ft. Not yet checked line by line: Alaska, Hawaii, Indiana, Iowa, Kentucky, Maryland, Minnesota, North Carolina, South Carolina, Tennessee, Vermont, Virginia and Wyoming; treat federal 5 ft as the floor there and ask the state agency or your safety person whether the plan adds anything. In every state the competent person and your company program decide what protection a trench gets.", "title": "State OSHA plans and trench protection depth: which rule book applies on your job", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "29 CFR 1926.652(a)(1); osha.gov/stateplans; Wash. Admin. Code 296-155-657; 8 CCR 341; Mich. Admin. Code R 408.40941; AZ R20-5-601; UT R614-1-4; OR 437-003-0001; NM 11.5.3.9 NMAC; checked 2026-11-20", "confidence": "medium"}]$kb$::jsonb) with ordinality as t(e, i),
       (select max(ord) as mx from pb_ai.kb_chunks where version = 'b3e91f6c47d2') m
 where not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' in ('dig-al', 'dig-ak', 'dig-az', 'dig-ar', 'dig-ca', 'dig-co', 'dig-ct', 'dig-de', 'dig-dc', 'dig-fl', 'dig-ga', 'dig-hi', 'dig-id', 'dig-il', 'dig-in', 'dig-ia', 'dig-ks', 'dig-ky', 'dig-la', 'dig-me', 'dig-md', 'dig-ma', 'dig-mi', 'dig-mn', 'dig-ms', 'dig-mo', 'dig-mt', 'dig-ne', 'dig-nv', 'dig-nh', 'dig-nj', 'dig-nm', 'dig-ny', 'dig-nc', 'dig-nd', 'dig-oh', 'dig-ok', 'dig-or', 'dig-pa', 'dig-ri', 'dig-sc', 'dig-sd', 'dig-tn', 'dig-tx', 'dig-ut', 'dig-vt', 'dig-va', 'dig-wa', 'dig-wv', 'dig-wi', 'dig-wy', 'dig-basics-1', 'plan-mi-trench-1', 'plan-or-confined-1', 'plan-wa-confined-1', 'plan-trench-depth-1'));

-- 2.1 chunk 71 (app-howto-locates-1) text: r17.06: ticket dates follow the job state; the "good for (days)" setting was replaced by "811 rules state"
update pb_ai.kb_chunks
   set chunk = jsonb_set(chunk, '{text}', to_jsonb(replace(chunk->>'text', $old$Each ticket shows Can dig from (2 working days after the call, the call day not counted) and Start work by (14 days after the call); a ticket is good for 28 days (Settings › Company: "A new dig ticket is good for (days)").$old$, $new$Each ticket shows Can dig from and Start work by, counted with the 811 rules of the job's state. The state comes from Change State on the Locates screen, else the job address, else Settings › Company › 811 rules state. Rules for the state (on the Locates screen) shows that state's wait, ticket life, tolerance zone, white lining and sources. Where a state's ticket life is not confirmed the app fills no expiry and Save asks for the date on the ticket. The numbers differ by state (for example a 28-day ticket in California and 14 working days in Texas), so go by the job's state, not by habit.$new$)))
 where version = 'b3e91f6c47d2' and ord = 71 and chunk->>'id' = 'app-howto-locates-1'
   and strpos(chunk->>'text', $old$Each ticket shows Can dig from (2 working days after the call, the call day not counted) and Start work by (14 days after the call); a ticket is good for 28 days (Settings › Company: "A new dig ticket is good for (days)").$old$) > 0;

-- 2.2 chunk 235 (app-data-other-reference-values-2) text: the 1-60 day company setting no longer exists (r17.06)
update pb_ai.kb_chunks
   set chunk = jsonb_set(chunk, '{text}', to_jsonb(replace(chunk->>'text', $old$a ticket is good for 28 days (company setting 1–60, default 28).$old$, $new$a ticket is good for 28 days. Jobs in other states use that state's own numbers from the app's state table (Locates › Rules for the state).$new$)))
