-- 3. the version's row count (the Ask loader refuses a build whose rows don't match kb_versions.n)
update pb_ai.kb_versions v
   set n = c.n, counts = c.counts
  from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts
          from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
 where v.version = 'b3e91f6c47d2';

-- 4. invalidate the cached search-index blob (same step as Nov 18 and Nov 19)
update pb_ai.kb_index set parts = 32 where version = 'b3e91f6c47d2';

-- check
select (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and chunk->>'id' in ('dig-al', 'dig-ak', 'dig-az', 'dig-ar', 'dig-ca', 'dig-co', 'dig-ct', 'dig-de', 'dig-dc', 'dig-fl', 'dig-ga', 'dig-hi', 'dig-id', 'dig-il', 'dig-in', 'dig-ia', 'dig-ks', 'dig-ky', 'dig-la', 'dig-me', 'dig-md', 'dig-ma', 'dig-mi', 'dig-mn', 'dig-ms', 'dig-mo', 'dig-mt', 'dig-ne', 'dig-nv', 'dig-nh', 'dig-nj', 'dig-nm', 'dig-ny', 'dig-nc', 'dig-nd', 'dig-oh', 'dig-ok', 'dig-or', 'dig-pa', 'dig-ri', 'dig-sc', 'dig-sd', 'dig-tn', 'dig-tx', 'dig-ut', 'dig-vt', 'dig-va', 'dig-wa', 'dig-wv', 'dig-wi', 'dig-wy', 'dig-basics-1', 'plan-mi-trench-1', 'plan-or-confined-1', 'plan-wa-confined-1', 'plan-trench-depth-1')) as new_chunks,
       (select n from pb_ai.kb_versions where version = 'b3e91f6c47d2') as n,
       (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2') as rows,
       (select strpos(chunk->>'text', '811 rules state') > 0 from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and ord = 71) as chunk71_edited,
       (select strpos(chunk->>'source', 'Florida') = 0 from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and ord = 699) as chunk699_edited,
       (select coalesce(jsonb_typeof(public.pb_ai_kb_boot()->'index'), 'null') <> 'object') as blob_not_used;

commit;
